let current='zh-CN';try{const saved=localStorage.getItem('test.uiLanguage');if(saved==='en'||saved==='zh-CN')current=saved;}catch{}
document.documentElement.lang=current;Promise.resolve(window.testLocale?.setLanguage(current)).catch(()=>{});
export const getLanguage=()=>current;
export function t(message,values=[]){const text=current==='zh-CN'?(dictionary[message]??message):message;return text.replace(/\{(\d+)\}/g,(_,i)=>String(values[Number(i)]??''));}
export async function setLanguage(language){if(!['zh-CN','en'].includes(language)||language===current)return;try{localStorage.setItem('test.uiLanguage',language);}catch{}current=language;document.documentElement.lang=language;try{await window.testLocale?.setLanguage(language);}catch{}window.location.reload();}
export function languageControl(jsx){return jsx.jsxs('label',{className:'test-language-control',children:[jsx.jsx('span',{children:t('Language')}),jsx.jsxs('select',{'aria-label':t('Interface language'),value:current,onChange:event=>void setLanguage(event.target.value),children:[jsx.jsx('option',{value:'zh-CN',children:'简体中文'}),jsx.jsx('option',{value:'en',children:'English'})]})]});}
